// Builds the token request for the old platform (probe).
// In: any message. Out: method, url and headers for the http node.
var cfg = glob.get('cfg');
var credentials = cfg.clientId + ':' + cfg.clientSecret;
msg.method = 'POST';
msg.url = 'https://' + cfg.tenantName +
  '.piam.eu1.mindsphere.io/oauth/token?grant_type=client_credentials';
msg.headers = {
  'Authorization': 'Basic ' + Buffer.from(credentials).toString('base64'),
  'Accept': 'application/json'
};
delete msg.payload;
return msg;

// Takes the token response and sends one request message per probe call.
// In: token response. Out 1: the calls. Out 2: token result summary.
var BASE = 'https://gateway.eu1.mindsphere.io/api/';
var cfg = glob.get('cfg');
var token = msg.payload && msg.payload.access_token;
if (msg.statusCode !== 200 || !token) {
  var failed = {
    step: 'token',
    status: msg.statusCode,
    error: msg.payload && msg.payload.error
  };
  return [null, { payload: failed }];
}
var assetId = cfg.sites[0].assetIds[0];
var oee = BASE + 'oee/v3';
var am = BASE + 'assetmanagement/v3';
var kpiBody = {
  assetId: assetId,
  scope: {
    from: '2026-09-30T00:00:00.000Z',
    to: '2026-10-01T00:00:00.000Z',
    filter: [
      { key: 'PRODUCT', value: [] },
      { key: 'ORDER', value: [] },
      { key: 'SHIFT', value: [] }
    ],
    recursive: false,
    groupedByDateTime: false
  }
};
var calls = [
  { name: 'oee health', method: 'GET', url: oee + '/health' },
  { name: 'oee assets', method: 'GET', url: oee + '/assets' },
  {
    name: 'am assets',
    method: 'GET',
    url: am + '/assets?size=1',
    accept: 'application/hal+json'
  },
  {
    name: 'oee evaluateKPIs',
    method: 'POST',
    url: oee + '/expressions/evaluateKPIs',
    body: JSON.stringify(kpiBody)
  }
];
var out = [];
for (var i = 0; i < calls.length; i++) {
  var call = calls[i];
  var request = {
    callName: call.name,
    method: call.method,
    url: call.url,
    headers: {
      'Authorization': 'Bearer ' + token,
      'Accept': call.accept || 'application/json'
    }
  };
  if (call.body) {
    request.headers['Content-Type'] = 'application/json';
    request.payload = call.body;
  }
  out.push(request);
}
return [out, { payload: { step: 'token', status: msg.statusCode } }];

// Reduces each response to its status and size. Never shows body or token.
// In: the http response. Out: msg.payload with call, status, bytes, results.
var text = typeof msg.payload === 'string' ? msg.payload : '';
var results = null;
try {
  var body = JSON.parse(text);
  if (body && Array.isArray(body.results)) {
    results = body.results.length;
  }
} catch (e) {
  results = null;
}
msg.payload = {
  call: msg.callName,
  status: msg.statusCode,
  bytes: text.length,
  results: results
};
return msg;
